  if (Thread.interrupted()) {
    InterruptedIOException ex = new InterruptedIOException("Thread interrupted during write");
    ex.bytesTransferred = bytesTransferred;
    Thread.currentThread().interrupt();
    throw ex;
  }
  return true;
}

